/**
 * Recipe tile schema (`building-recipes/14/x/y.json`): one object per BAG pand that the near tier draws.
 *
 * The tile is generated by `scripts/building-tiles/compile-recipes.ts` and never hand-edited; faces
 * (`scripts/block-face/faces/<id>/intent.json`), house recipes (`scripts/building-recipes/houses/<id>/intent.json`),
 * building types (`public/canal-drive/building-types/instances.json`) and the landmark catalogue stay the authoring
 * units. A pand without an entry is generic: the streamed facade draws it. Design decisions and their reasons are in
 * docs/buildings-pipeline.md "Recipe tiles".
 */
import {ARCHETYPES, type MidDescriptor} from '../bagTiles.ts';
import {GABLES} from '../buildingRecipe/intent.ts';
import {MATERIAL_SLOTS, type MaterialSlot} from '../look/palette.ts';

export const RECIPE_TILE_VERSION = 1;

export const PAND_KINDS = ['canal-house', 'type', 'large', 'kit', 'glb'] as const;
export type PandKind = (typeof PAND_KINDS)[number];

/**
 * Where a pand's authoring lives, as one compact reference:
 *   face:<faceId>/<houseIndex>   a house of a block face (faces/<faceId>/intent.json houses[i])
 *   house:<recipeId>             a house recipe (houses/<id>/intent.json; canal-house or large)
 *   type:<unit>                  a building-types unit (building-types/<unit>.glb, placement from instances.json)
 *   kit:<kitId>                  a parametric landmark kit (landmarkKits.ts)
 *   model:<specId>               an installed GLB model (landmark or ordinary catalogue spec id)
 */
export type IntentRef = string;
export const INTENT_REF = /^(face:[\w.-]+\/\d+|house:[\w.-]+|type:[\w.-]+|kit:[\w.-]+|model:[\w.-]+)$/;
export const intentScheme = (ref: IntentRef): 'face' | 'house' | 'type' | 'kit' | 'model' => ref.slice(0, ref.indexOf(':')) as any;
/** Which kinds each reference scheme may carry. */
const SCHEME_KINDS: Record<ReturnType<typeof intentScheme>, readonly PandKind[]> = {
  face: ['canal-house'], house: ['canal-house', 'large'], type: ['type'], kit: ['kit'], model: ['glb'],
};

/**
 * The near tier's mid-tier descriptor of a pand: the facts sidecar's seven fields (bagTiles.ts `MidDescriptor`) plus
 * what only the recipe knows. About 40 bytes as JSON.
 *   [archetype, storeys, roof, eavesDm, ridgeDm, year, terraced, bays, wall, gable, shop]
 * bays: window axes of the main front (0 unknown); wall: 1 + MATERIAL_SLOTS index of the wall slot (0 unknown);
 * gable: 1 + GABLES index of the main front's crown (0 unknown / none); shop: 1 when the ground storey is a shopfront.
 */
export type RecipeMid = [...MidDescriptor, bays: number, wall: number, gable: number, shop: 0 | 1];
export const MID_LENGTH = 11;

export const wallCode = (slot: MaterialSlot | null | undefined): number => (slot ? MATERIAL_SLOTS.indexOf(slot) + 1 : 0);
export const gableCode = (gable: string | null | undefined): number => (gable ? (GABLES as readonly string[]).indexOf(gable) + 1 : 0);
export function decodeRecipeMid(row: readonly number[]) {
  return {
    archetype: ARCHETYPES[row[0]] ?? 'unknown', storeys: row[1], roof: row[2], eavesM: row[3] > 0 ? row[3] / 10 : null, ridgeM: row[4] > 0 ? row[4] / 10 : null,
    year: row[5] > 0 ? row[5] : null, terraced: row[6] === 1, bays: row[7], wall: row[8] > 0 ? MATERIAL_SLOTS[row[8] - 1] : null,
    gable: row[9] > 0 ? GABLES[row[9] - 1] : null, shop: row[10] === 1,
  };
}

/**
 * Compiler-written results of the fit (never authored). Recipe kinds carry the measured storeys; placed kinds carry the
 * placement the compiler baked (anchor + yaw + scale, the same numbers `signaturePlacement.placementFor` or
 * `buildingTypes/runtime.ts instanceMatrix` would use at runtime).
 */
export interface Fitted {
  /** Main front: eaves above the street level, storey heights, front width. */
  eavesM?: number;
  storeyHeightsM?: number[];
  frontWidthM?: number;
  /** Highest roof point above the street level (model). */
  roofMaxM?: number;
  /** Street-level shift applied by the face ground plan (m). */
  groundShiftM?: number;
  /** Placed kinds: anchor [lng, lat], yaw (degrees clockwise from glTF +X east), scale, mirrored. */
  placement?: {anchor: [number, number]; yawDeg: number; scale: [number, number, number]; mirror?: boolean};
  /** Triangles the near tier draws for the pand. */
  triangles?: number;
}

export interface PandRecipe {
  kind: PandKind;
  /** Exactly one of `intent` and `sameAs`. */
  intent?: IntentRef;
  /** Another pand (16-digit id, same recipe tile set) whose recipe this one repeats, with `overrides` merged in. */
  sameAs?: string;
  overrides?: Record<string, unknown>;
  fitted?: Fitted;
  mid: RecipeMid;
  /** Ids the near tier hides in the mid/far layers while it draws this pand: `NL.IMBAG.Pand.*` and OSM-only ids. */
  covers: string[];
  /** The z16 mesh tile that draws it ([x, y]). */
  mesh: [number, number];
}

export interface RecipeTile {
  version: typeof RECIPE_TILE_VERSION;
  z: 14; x: number; y: number;
  /** Fingerprints of the authoring inputs the tile was generated from (provenance + invalidation). */
  sources: Record<string, string>;
  /**
   * Keyed by the 16-digit pand id; a model standing on no pand (a monument on a square) is keyed `m:<specId>`.
   * A model covering several pands is one entry under its primary pand, the rest in its `covers`.
   */
  pands: Record<string, PandRecipe>;
}

export const PAND_KEY = /^(\d{16}|m:[\w.-]+)$/;

/** Validate a parsed recipe tile. Returns the problems (empty = valid); `strict` also requires `fitted`. */
export function recipeTileProblems(input: unknown, opts: {strict?: boolean} = {}): string[] {
  const t = input as RecipeTile, problems: string[] = [];
  if (!t || typeof t !== 'object') return ['not an object'];
  if (t.version !== RECIPE_TILE_VERSION) problems.push(`version must be ${RECIPE_TILE_VERSION}`);
  if (t.z !== 14 || !Number.isInteger(t.x) || !Number.isInteger(t.y)) problems.push('z must be 14 with integer x, y');
  if (!t.sources || typeof t.sources !== 'object') problems.push('sources must be an object');
  if (!t.pands || typeof t.pands !== 'object') return [...problems, 'pands must be an object'];
  const n = 2 ** 2;
  for (const [key, p] of Object.entries(t.pands)) {
    const at = (s: string) => problems.push(`${key}: ${s}`);
    if (!PAND_KEY.test(key)) at('key must be a 16-digit pand id or m:<specId>');
    if (!(PAND_KINDS as readonly string[]).includes(p.kind)) at(`kind ${p.kind} not in ${PAND_KINDS.join('|')}`);
    if ((p.intent === undefined) === (p.sameAs === undefined)) at('exactly one of intent and sameAs');
    if (p.intent !== undefined) {
      if (!INTENT_REF.test(p.intent)) at(`intent ${p.intent} is not a reference (face:/house:/type:/kit:/model:)`);
      else if (!SCHEME_KINDS[intentScheme(p.intent)].includes(p.kind)) at(`intent ${p.intent} cannot carry kind ${p.kind}`);
    }
    if (p.sameAs !== undefined) {
      if (!/^\d{16}$/.test(p.sameAs)) at('sameAs must be a 16-digit pand id');
      else if (p.sameAs === key) at('sameAs points at itself');
    }
    if (p.overrides !== undefined && (p.sameAs === undefined || typeof p.overrides !== 'object' || Array.isArray(p.overrides))) at('overrides only with sameAs, as an object');
    if (!Array.isArray(p.mid) || p.mid.length !== MID_LENGTH || !p.mid.every(v => Number.isInteger(v) && v >= 0)) at(`mid must be ${MID_LENGTH} non-negative integers`);
    else if (p.mid[0] >= ARCHETYPES.length) at('mid archetype out of range');
    if (!Array.isArray(p.covers) || !p.covers.every(c => typeof c === 'string' && c.length > 0)) at('covers must be a list of ids');
    else if (/^\d{16}$/.test(key) && p.kind !== 'glb' && !p.covers.includes(`NL.IMBAG.Pand.${key}`)) at('a pand drawn by its recipe covers itself');
    if (!Array.isArray(p.mesh) || p.mesh.length !== 2 || Math.floor(p.mesh[0] / n) !== t.x || Math.floor(p.mesh[1] / n) !== t.y) at('mesh must name a z16 tile inside this z14 tile');
    if (opts.strict && !p.fitted) at('fitted missing (run the mesh stage, then assemble)');
    if (p.fitted?.placement) {
      const pl = p.fitted.placement;
      if (pl.anchor.length !== 2 || pl.scale.length !== 3 || !Number.isFinite(pl.yawDeg)) at('fitted.placement malformed');
    }
  }
  // sameAs targets: present, same kind, not themselves sameAs (one hop).
  for (const [key, p] of Object.entries(t.pands)) {
    if (!p.sameAs) continue;
    const target = t.pands[p.sameAs];
    if (!target) continue; // may live in a neighbouring tile; the compiler resolves across the set
    if (target.kind !== p.kind) problems.push(`${key}: sameAs ${p.sameAs} has kind ${target.kind}`);
    if (target.sameAs) problems.push(`${key}: sameAs ${p.sameAs} is itself sameAs (one hop only)`);
  }
  return problems;
}

export function validateRecipeTile(input: unknown, opts: {strict?: boolean} = {}): RecipeTile {
  const problems = recipeTileProblems(input, opts);
  if (problems.length) throw Error(`invalid recipe tile:\n  ${problems.join('\n  ')}`);
  return input as RecipeTile;
}

/** Stable JSON (sorted keys): the recipe tile is diffable and hashable. */
export function stableJson(value: unknown, indent?: number): string {
  const sort = (v: unknown): unknown => Array.isArray(v) ? v.map(sort) : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v as object).sort().map(k => [k, sort((v as any)[k])])) : v;
  return JSON.stringify(sort(value), null, indent);
}

// ---------------------------------------------------------------------------------------------------------------
// Mesh tile metadata (the root `extras.recipeTile` of building-mesh/16/x/y.glb and the index)

export const MESH_TILE_VERSION = 1;

/** Submesh roles. Hashable parts may become instanced units; the rest always stay in the tile's merged mesh. */
export const PART_ROLES = ['ground', 'body', 'crown', 'roof', 'rear', 'party', 'signage', 'whole'] as const;
export type PartRole = (typeof PART_ROLES)[number];
export const INSTANCEABLE_ROLES: readonly PartRole[] = ['ground', 'body', 'crown', 'whole'];

export interface MeshTileMeta {
  version: typeof MESH_TILE_VERSION;
  tile: [number, number, number];
  /** Tile-frame origin (tile centre) [lng, lat]. */
  anchor: [number, number];
  /** Pands drawn, in index order (`pandRanges` and the instance `_PAND` attribute index this list). */
  pands: string[];
  /** Per pand index: ids hidden in the mid/far layers while the tile is resident. */
  covers: string[][];
  /** Landmark/ordinary/chunk spec ids whose drawing this tile replaces while resident. */
  specs: string[];
  /** Units referenced by the tile's instance nodes. */
  units: {hash: string; triangles: number}[];
  /** Per pand index: short label for hover (address or model name). */
  names: string[];
}

export interface MeshIndex {
  version: typeof MESH_TILE_VERSION;
  /** Every published z16 tile id with its byte size and pand count. */
  tiles: Record<string, {bytes: number; pands: number; triangles: number; units: string[]}>;
  units: Record<string, {bytes: number; triangles: number}>;
}
